[CmdletBinding()]
param([ValidateSet('Inspect','Build','Backup','Apply','Verify','Rollback')][string]$Mode='Inspect',[switch]$Execute)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
[Console]::OutputEncoding=New-Object Text.UTF8Encoding($false);$OutputEncoding=[Console]::OutputEncoding
$env:DOCKER_HOST='npipe:////./pipe/dockerDesktopLinuxEngine';$env:DOCKER_CONFIG='C:/Users/TemichevVet/.docker';$env:Path='C:/Program Files/Docker/Docker/resources/bin;'+$env:Path
$root='C:/Users/TemichevVet/TemichevVet';$packet=$PSScriptRoot;$stage=Split-Path $packet -Parent
function Invoke-HotelReleaseDocker([string[]]$A){$saved=$ErrorActionPreference;try{$ErrorActionPreference='Continue';$t=& docker @A 2>&1|Out-String;$c=$LASTEXITCODE}finally{$ErrorActionPreference=$saved};if($c -ne 0){throw ('Docker '+$A[0]+' failed: '+$t)};return $t}
function Read-HotelReleaseJson([string]$P){return ConvertFrom-Json -InputObject ([IO.File]::ReadAllText($P))}
function Get-HotelReleaseHash([string]$P){return (Get-FileHash -LiteralPath $P -Algorithm SHA256).Hash.ToLowerInvariant()}
function Atomic([string]$P,[byte[]]$B){$t=$P+'.hotel-tariffs.tmp';$old=$P+'.hotel-tariffs.replaced.tmp';if((Test-Path $t) -or (Test-Path $old)){throw 'Previous atomic write needs inspection'};[IO.File]::WriteAllBytes($t,$B);if(Test-Path $P){[IO.File]::Replace($t,$P,$old);Remove-Item -LiteralPath $old -Force}else{[IO.File]::Move($t,$P)}}
function Save([string]$P,$V){Atomic $P ([Text.Encoding]::UTF8.GetBytes(($V|ConvertTo-Json -Depth 64)))}
function Get-HotelReleaseContainer([string]$N){return (ConvertFrom-Json -InputObject (Invoke-HotelReleaseDocker @('inspect',$N)))[0]}
function Get-HotelReleaseImage([string]$N){return (ConvertFrom-Json -InputObject (Invoke-HotelReleaseDocker @('image','inspect',$N)))[0]}
$m=Read-HotelReleaseJson ($packet+'/release.json');$backup=$root+'/backups/manual-releases/'+$m.releaseId;$statePath=$backup+'/release-state.json';$builtPath=$stage+'/built.private.json'
if($env:COMPUTERNAME -ne $m.host -or $m.releaseId -ne 'crm-pet-hotel-client-tariffs-20261023-r1' -or $m.revision -ne 'c43e0e8c8dd46de80a4616072b1a8f9d2826d1c1'){throw 'Wrong host or packet'}
if($Mode -in @('Build','Backup','Apply','Rollback') -and -not $Execute){throw 'Explicit execution required'}
foreach($f in (Read-HotelReleaseJson ($stage+'/packet-checksums.json')).PSObject.Properties){if((Get-HotelReleaseHash ($packet+'/'+$f.Name)) -ne $f.Value){throw ('Packet differs: '+$f.Name)}}
function Protected{foreach($old in $m.protected){$n=Get-HotelReleaseContainer $old.name;if($n.Id -ne $old.id -or $n.Image -ne $old.image -or $n.State.StartedAt -ne $old.startedAt -or -not $n.State.Running){throw ('Protected service changed: '+$old.name)}}}
function Baseline{Protected;foreach($key in @('api','web')){$old=$m.previous.$key;$now=Get-HotelReleaseContainer $old.name;if($now.Id -ne $old.id -or $now.Image -ne $old.image -or $now.State.StartedAt -ne $old.startedAt){throw ('Baseline changed: '+$key)};if((Get-HotelReleaseImage $old.reference).Id -ne $old.image){throw 'Base tag changed'}};foreach($f in $m.configuration){if((Get-HotelReleaseHash ($root+'/'+$f.name)) -ne $f.sha256){throw ('Configuration changed: '+$f.name)}}}
$compose=@('compose','--project-directory',$root,'--project-name','temichevvet','--file',($root+'/docker-compose.yml'),'--env-file',($root+'/.env'),'--env-file',($root+'/.env.runtime'))
function Config{return ConvertFrom-Json -InputObject (Invoke-HotelReleaseDocker ($compose+@('config','--format','json')))}
function ConfigDiff($Before,$After){if($After.services.api.image -ne $m.candidate.api.reference -or $After.services.web.image -ne $m.candidate.web.reference -or [string]$After.services.api.environment.SEED_ON_START -ne 'false'){throw 'Candidate pins or seed state differ'};$copy=ConvertFrom-Json -InputObject ($After|ConvertTo-Json -Depth 64);$copy.services.api.image=$Before.services.api.image;$copy.services.web.image=$Before.services.web.image;$copy.services.api.environment.CRM_SOURCE_VERSION=$Before.services.api.environment.CRM_SOURCE_VERSION;if(($Before|ConvertTo-Json -Depth 64 -Compress) -ne ($copy|ConvertTo-Json -Depth 64 -Compress)){throw 'Compose change exceeds API/Web image and API source revision'}}
function Healthy([string]$Api,[string]$Web,[string]$Revision){for($i=0;$i -lt 60;$i++){try{$a=Get-HotelReleaseContainer 'clinic-crm-api';$w=Get-HotelReleaseContainer 'clinic-crm-web';if($a.Image -ne $Api -or $w.Image -ne $Web -or -not $a.State.Running -or -not $w.State.Running){throw 'Image not ready'};$h=Invoke-RestMethod 'http://127.0.0.1:3000/api/health' -TimeoutSec 4;$r=Invoke-RestMethod 'http://127.0.0.1:3000/release.json' -TimeoutSec 4;if($h.status -ne 'ok' -or $h.database -ne 'ok' -or $r.revision -ne $Revision){throw 'Health or release differs'};return}catch{Start-Sleep -Milliseconds 750}};throw 'Health failed'}
function CheckState($s){if($s.releaseId -ne $m.releaseId -or $s.manifestSha256 -ne (Get-HotelReleaseHash ($packet+'/release.json')) -or (Get-HotelReleaseHash ($backup+'/database.dump')) -ne $s.databaseSha256 -or -not $s.restoreTested){throw 'Release state or backup differs'};foreach($k in @('api','web')){if((Get-HotelReleaseImage $m.candidate.$k.reference).Id -ne $s.candidate.$k){throw 'Candidate tag changed'}};Protected}
function NodeInApi([string]$File,[string[]]$Arguments=@()){$target='/tmp/hotel-client-tariffs-'+[IO.Path]::GetFileName($File);$null=Invoke-HotelReleaseDocker @('cp',$File,('clinic-crm-api:'+$target));return Invoke-HotelReleaseDocker (@('exec','clinic-crm-api','node',$target)+$Arguments)}
function RollbackPermission{$p=NodeInApi ($packet+'/migration-status.cjs');$migrated=(ConvertFrom-Json -InputObject $p).applied;if($migrated){$null=Invoke-HotelReleaseDocker @('cp',($packet+'/rollback-plan.json'),'clinic-crm-api:/tmp/hotel-tariffs-rollback-plan.json');$null=NodeInApi ($packet+'/rollback-permission.cjs') @('/tmp/hotel-tariffs-rollback-plan.json')}}
function RestorePins($s){foreach($f in $s.configuration){$now=Get-HotelReleaseHash ($root+'/'+$f.name);if($now -ne $f.sha256 -and $now -ne $f.appliedHash){throw ('Unrelated configuration retained: '+$f.name)}};foreach($f in $s.configuration){Atomic ($root+'/'+$f.name) ([IO.File]::ReadAllBytes(($backup+'/'+$f.savedName)))}}
function RollbackRelease($s){RestorePins $s;$null=Invoke-HotelReleaseDocker ($compose+@('up','-d','--no-deps','--no-build','--pull','never','api','web'));Healthy $m.previous.api.image $m.previous.web.image $m.webBaseRevision;RollbackPermission;Protected;$s.phase='ROLLED_BACK';Save $statePath $s}
switch($Mode){
 'Inspect'{Baseline;$cfg=Config;if($cfg.services.api.image -ne $m.previous.api.reference -or $cfg.services.web.image -ne $m.previous.web.reference){throw 'Running images differ from configured pins'};[pscustomobject]@{status='INSPECTED';api=$cfg.services.api.image;web=$cfg.services.web.image;seed=$cfg.services.api.environment.SEED_ON_START}|ConvertTo-Json;break}
 'Build'{
  Baseline;if(Test-Path $builtPath){throw 'Candidate evidence already exists; inspect before retrying'}
  foreach($key in @('api','web')){$out=Invoke-HotelReleaseDocker @('build','--platform','linux/amd64','--network','none','--pull=false','-f',($packet+'/Dockerfile.'+$key),'-t',$m.candidate.$key.reference,$packet);[IO.File]::WriteAllText(($stage+'/build-'+$key+'.log'),$out);$base=Get-HotelReleaseImage $m.previous.$key.reference;$candidate=Get-HotelReleaseImage $m.candidate.$key.reference;if($candidate.Architecture -ne 'amd64' -or $candidate.Config.Labels.'io.temichevvet.component-source' -ne $m.revision){throw 'Candidate architecture or label differs'};foreach($prop in @('Entrypoint','Cmd','Env','WorkingDir','User')){$bp=$base.Config.PSObject.Properties[$prop];$np=$candidate.Config.PSObject.Properties[$prop];$bv=$null;$nv=$null;if($null -ne $bp){$bv=$bp.Value};if($null -ne $np){$nv=$np.Value};if(($bv|ConvertTo-Json -Compress) -ne ($nv|ConvertTo-Json -Compress)){throw ('Inherited configuration changed: '+$prop)}}}
  $hashCode="const f=require('fs'),c=require('crypto');let a={};function walk(p){for(const n of f.readdirSync(p)){const q=p+'/'+n;if(f.statSync(q).isDirectory())walk(q);else a[q]=c.createHash('sha256').update(f.readFileSync(q)).digest('hex')}}walk('/app/apps/api/dist');walk('/app/prisma/migrations');console.log(JSON.stringify(a));"
  $b=ConvertFrom-Json -InputObject (Invoke-HotelReleaseDocker @('run','--rm','--network','none','--entrypoint','node',$m.previous.api.reference,'-e',$hashCode));$n=ConvertFrom-Json -InputObject (Invoke-HotelReleaseDocker @('run','--rm','--network','none','--entrypoint','node',$m.candidate.api.reference,'-e',$hashCode));$allowed=@($m.allowedApiPaths)+@('/app/prisma/migrations/'+$m.migration+'/migration.sql');$changed=@();foreach($f in $b.PSObject.Properties){$v=$n.PSObject.Properties[$f.Name];if($null -eq $v){throw ('Candidate removed file: '+$f.Name)};if($v.Value -ne $f.Value){if($f.Name -notin $allowed){throw ('Unrelated API change: '+$f.Name)};$changed+=$f.Name}};foreach($f in $n.PSObject.Properties){if($null -eq $b.PSObject.Properties[$f.Name] -and $f.Name -notin $allowed){throw ('Unrelated API addition: '+$f.Name)}}
  if($n.PSObject.Properties['/app/prisma/migrations/'+$m.migration+'/migration.sql'].Value -ne $m.migrationSha256){throw 'Candidate migration differs'}
  Baseline;Save $builtPath ([pscustomobject]@{releaseId=$m.releaseId;at=[DateTime]::UtcNow.ToString('o');api=(Get-HotelReleaseImage $m.candidate.api.reference).Id;web=(Get-HotelReleaseImage $m.candidate.web.reference).Id;changedApiPaths=$changed;preservedApiFiles=@($b.PSObject.Properties).Count});Write-Output 'BUILT_SCOPED_CANDIDATES';break
 }
 'Backup'{
  Baseline;$built=Read-HotelReleaseJson $builtPath;if(Test-Path $backup){throw 'Backup exists; inspect evidence before retrying'};$null=New-Item -ItemType Directory -Path $backup;$who=[Security.Principal.WindowsIdentity]::GetCurrent().Name;& icacls $backup /inheritance:r /grant:r ($who+':(OI)(CI)F') 'SYSTEM:(OI)(CI)F' *> $null;if($LASTEXITCODE -ne 0){throw 'Private backup ACL failed'}
  $files=@();foreach($f in $m.configuration){$saved='before-'+$f.name.Replace('/','-');[IO.File]::WriteAllBytes(($backup+'/'+$saved),[IO.File]::ReadAllBytes(($root+'/'+$f.name)));$files+=[pscustomobject]@{name=$f.name;sha256=$f.sha256;savedName=$saved;appliedHash=''}}
  $pg=Get-HotelReleaseContainer 'clinic-crm-postgres';$u=@($pg.Config.Env|Where-Object{$_ -like 'POSTGRES_USER=*'})[0].Substring(14);$db=@($pg.Config.Env|Where-Object{$_ -like 'POSTGRES_DB=*'})[0].Substring(12);$suffix=[guid]::NewGuid().ToString('N').Substring(0,12);$restore='hotel-tariffs-restore-'+$suffix;$qa='hotel-tariffs-qualify-'+$suffix;$dump='/tmp/hotel-tariffs-'+$suffix+'.dump';$restoreStarted=$false;$qaStarted=$false
  try{
   $null=Invoke-HotelReleaseDocker @('exec','clinic-crm-postgres','pg_dump','-U',$u,'-d',$db,'-Fc','--file',$dump);$null=Invoke-HotelReleaseDocker @('cp',('clinic-crm-postgres:'+$dump),($backup+'/database.dump'))
   $null=Invoke-HotelReleaseDocker @('run','-d','--pull','never','--network','none','--name',$restore,'--label',('io.temichevvet.release='+$m.releaseId),'-e','POSTGRES_USER=restore_test','-e','POSTGRES_DB=restore_test','-e','POSTGRES_PASSWORD=isolated-restore-only',$pg.Image);$restoreStarted=$true
   $ready=$false;for($i=0;$i -lt 60;$i++){try{$null=Invoke-HotelReleaseDocker @('exec',$restore,'pg_isready','-h','127.0.0.1','-U','restore_test','-d','restore_test');$ready=$true;break}catch{Start-Sleep -Milliseconds 500}};if(-not $ready){throw 'Restore database did not start'}
   $null=Invoke-HotelReleaseDocker @('cp',($backup+'/database.dump'),($restore+':/tmp/database.dump'));$null=Invoke-HotelReleaseDocker @('exec',$restore,'pg_restore','-U','restore_test','-d','restore_test','--no-owner','--no-privileges','--exit-on-error','/tmp/database.dump')
   $null=Invoke-HotelReleaseDocker @('run','-d','--pull','never','--name',$qa,'--network',('container:'+$restore),'-e','DATABASE_URL=postgresql://restore_test:isolated-restore-only@127.0.0.1:5432/restore_test','-e','NODE_ENV=test','--entrypoint','sh',$m.candidate.api.reference,'-c','sleep 1800');$qaStarted=$true
   foreach($name in @('qualify.cjs','rollback-permission.cjs','rollback-plan.json','protected-snapshot.cjs')){$null=Invoke-HotelReleaseDocker @('cp',($packet+'/'+$name),($qa+':/tmp/'+$name))}
   $rowsBefore=(Invoke-HotelReleaseDocker @('exec',$qa,'node','/tmp/protected-snapshot.cjs')).Trim();$migrate=Invoke-HotelReleaseDocker @('exec',$qa,'node','/app/node_modules/prisma/build/index.js','migrate','deploy','--schema','/app/prisma/schema.prisma');[IO.File]::WriteAllText(($backup+'/restore-migration.log'),$migrate)
   $rowsAfter=(Invoke-HotelReleaseDocker @('exec',$qa,'node','/tmp/protected-snapshot.cjs')).Trim();if($rowsBefore -ne $rowsAfter){throw 'Migration changed protected restored data'}
   $qualified=Invoke-HotelReleaseDocker @('exec',$qa,'node','/tmp/qualify.cjs');[IO.File]::WriteAllText(($backup+'/candidate-qualification.json'),$qualified)
   $rollback=Invoke-HotelReleaseDocker @('exec',$qa,'node','/tmp/rollback-permission.cjs','/tmp/rollback-plan.json');[IO.File]::WriteAllText(($backup+'/rollback-rehearsal.json'),$rollback)
   $null=Invoke-HotelReleaseDocker @('exec',$qa,'node','/app/node_modules/prisma/build/index.js','migrate','deploy','--schema','/app/prisma/schema.prisma')
   if($rowsBefore -ne (Invoke-HotelReleaseDocker @('exec',$qa,'node','/tmp/protected-snapshot.cjs')).Trim()){throw 'Rollback rehearsal changed protected restored data'}
   Baseline;$state=[pscustomobject]@{releaseId=$m.releaseId;revision=$m.revision;manifestSha256=(Get-HotelReleaseHash ($packet+'/release.json'));phase='PREPARED';preparedAt=[DateTime]::UtcNow.ToString('o');candidate=[pscustomobject]@{api=$built.api;web=$built.web};configuration=$files;databaseSha256=(Get-HotelReleaseHash ($backup+'/database.dump'));restoreTested=$true;candidateQualified=$true;rollbackRehearsed=$true;completedAt=$null};Save $statePath $state;Write-Output 'BACKUP_RESTORED_CANDIDATE_AND_ROLLBACK_QUALIFIED'
  }finally{if($qaStarted){$null=Invoke-HotelReleaseDocker @('rm','-f','-v',$qa)};if($restoreStarted){$null=Invoke-HotelReleaseDocker @('rm','-f','-v',$restore)};$null=Invoke-HotelReleaseDocker @('exec','clinic-crm-postgres','rm','-f',$dump)};break
 }
 'Apply'{
  Baseline;$s=Read-HotelReleaseJson $statePath;CheckState $s;if($s.phase -ne 'PREPARED' -or [DateTime]::Parse($s.preparedAt).ToUniversalTime() -lt [DateTime]::UtcNow.AddHours(-2)){throw 'Fresh qualified backup required'};$before=Config
  foreach($f in $s.configuration){$p=$root+'/'+$f.name;$bytes=[IO.File]::ReadAllBytes($p);if($f.name -in @('.env','.env.runtime')){$text=[IO.File]::ReadAllText($p);foreach($key in @('TEMICHEVVET_API_IMAGE','TEMICHEVVET_REMOTE_API_IMAGE','TEMICHEVVET_WEB_IMAGE','TEMICHEVVET_REMOTE_WEB_IMAGE','CRM_SOURCE_VERSION')){$pattern='(?m)^'+$key+'=[^\r\n]*';$count=[regex]::Matches($text,$pattern).Count;if($count -gt 1){throw 'Duplicate release pin'};if($count -eq 1){$v=if($key -eq 'CRM_SOURCE_VERSION'){$m.revision}elseif($key -match 'WEB'){$m.candidate.web.reference}else{$m.candidate.api.reference};$text=[regex]::Replace($text,$pattern,($key+'='+$v))}};$bom=$bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191;$enc=New-Object Text.UTF8Encoding($bom);$bytes=[byte[]](@($enc.GetPreamble())+@($enc.GetBytes($text)))}elseif($f.name -eq 'diagnostics/bin/system-diagnostics-config.json'){$d=Read-HotelReleaseJson $p;foreach($prop in @('expectedRevision','expectedApiImage','expectedWebImage')){if($null -ne $d.PSObject.Properties[$prop]){$v=if($prop -eq 'expectedRevision'){$m.revision}elseif($prop -eq 'expectedApiImage'){$m.candidate.api.reference}else{$m.candidate.web.reference};$d.$prop=$v}};$bytes=[Text.Encoding]::UTF8.GetBytes(($d|ConvertTo-Json -Depth 32))};[IO.File]::WriteAllBytes(($backup+'/planned-'+$f.savedName),$bytes);$f.appliedHash=Get-HotelReleaseHash ($backup+'/planned-'+$f.savedName)};Save $statePath $s
  try{
   foreach($f in $s.configuration){Atomic ($root+'/'+$f.name) ([IO.File]::ReadAllBytes(($backup+'/planned-'+$f.savedName)))};ConfigDiff $before (Config)
   # The inherited scoped entrypoint deliberately skips migrations. Run only Prisma CLI, with no application workers or seeding.
   $null=Invoke-HotelReleaseDocker @('cp',($packet+'/rollback-plan.json'),'clinic-crm-api:/tmp/hotel-tariffs-rollback-plan.json');$null=NodeInApi ($packet+'/assert-migrations.cjs') @('/tmp/hotel-tariffs-rollback-plan.json')
   $s.phase='MIGRATING';Save $statePath $s;$null=Invoke-HotelReleaseDocker @('cp',($packet+'/migration/'+$m.migration),('clinic-crm-api:/app/prisma/migrations/'+$m.migration));$migration=Invoke-HotelReleaseDocker @('exec','clinic-crm-api','node','/app/node_modules/prisma/build/index.js','migrate','deploy','--schema','/app/prisma/schema.prisma');[IO.File]::WriteAllText(($backup+'/live-migration.log'),$migration)
   $s.phase='SWITCHING';Save $statePath $s;$null=Invoke-HotelReleaseDocker ($compose+@('up','-d','--no-deps','--no-build','--pull','never','api','web'));Healthy $s.candidate.api $s.candidate.web $m.revision;Protected
   $dbState=ConvertFrom-Json -InputObject (NodeInApi ($packet+'/migration-status.cjs'));if(-not $dbState.applied -or -not $dbState.administratorCanManage){throw 'Administrator grant not active'}
   $s.phase='COMPLETE';$s.completedAt=[DateTime]::UtcNow.ToString('o');Save $statePath $s;Write-Output 'PRODUCTION_RELEASE_COMPLETE'
  }catch{$failure=$_;RollbackRelease $s;throw $failure};break
 }
 'Verify'{$s=Read-HotelReleaseJson $statePath;CheckState $s;if($s.phase -ne 'COMPLETE'){throw 'Release is not complete'};Healthy $s.candidate.api $s.candidate.web $m.revision;foreach($f in $s.configuration){if((Get-HotelReleaseHash ($root+'/'+$f.name)) -ne $f.appliedHash){throw 'Configuration drift after release'}};$dbState=ConvertFrom-Json -InputObject (NodeInApi ($packet+'/migration-status.cjs'));if(-not $dbState.applied -or -not $dbState.administratorCanManage){throw 'Permission migration missing'};[pscustomobject]@{status='VERIFIED';revision=$m.revision;candidate=$s.candidate;backup=$backup;databaseSha256=$s.databaseSha256;restoreTested=$s.restoreTested;rollbackRehearsed=$s.rollbackRehearsed;protectedServices=4;database=$dbState}|ConvertTo-Json -Depth 16;break}
 'Rollback'{$s=Read-HotelReleaseJson $statePath;CheckState $s;foreach($k in @('api','web')){if((Get-HotelReleaseContainer $m.previous.$k.name).Image -ne $s.candidate.$k){throw 'Rollback refuses unrelated deployment'}};RollbackRelease $s;Write-Output 'PRODUCTION_ROLLED_BACK_WITH_BUSINESS_DATA_RETAINED';break}
}
